import type { HTMLAttributes, TableHTMLAttributes, TdHTMLAttributes, ThHTMLAttributes } from "react";

function join(base: string, extra = "") { return `${base} ${extra}`.trim(); }
export function Table({ className, ...props }: TableHTMLAttributes<HTMLTableElement>) { return <div className="co-w-full co-overflow-auto"><table className={join("co-w-full co-caption-bottom co-text-sm", className)} {...props} /></div>; }
export function TableHeader({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) { return <thead className={join("[&_tr]:co-border-b", className)} {...props} />; }
export function TableBody({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) { return <tbody className={join("[&_tr:last-child]:co-border-0", className)} {...props} />; }
export function TableFooter({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) { return <tfoot className={join("co-border-t co-bg-black/5 co-font-medium", className)} {...props} />; }
export function TableRow({ className, ...props }: HTMLAttributes<HTMLTableRowElement>) { return <tr className={join("co-border-b co-transition hover:co-bg-black/5", className)} {...props} />; }
export function TableHead({ className, ...props }: ThHTMLAttributes<HTMLTableCellElement>) { return <th className={join("co-h-11 co-px-3 co-text-left co-align-middle co-font-medium co-text-black/60", className)} {...props} />; }
export function TableCell({ className, ...props }: TdHTMLAttributes<HTMLTableCellElement>) { return <td className={join("co-p-3 co-align-middle", className)} {...props} />; }
export function TableCaption({ className, ...props }: HTMLAttributes<HTMLTableCaptionElement>) { return <caption className={join("co-mt-4 co-text-sm co-text-black/60", className)} {...props} />; }
